html:
{#
  Ex Student Writeoff — Print Format
  Style: Matches Dux Receipt Voucher layout (red accent for write-off)
#}

{%- set company_doc = frappe.get_doc("Company", doc.company) %}
{%- set _raw_logo   = company_doc.get("custom_voucher_print_logo") %}
{%- if _raw_logo %}
  {%- set logo_url = frappe.utils.get_url(_raw_logo) %}
{%- else %}
  {%- set logo_url = frappe.utils.get_url("/assets/dux_voucher/images/dv_logo.png") %}
{%- endif %}
{%- set currency    = company_doc.get("default_currency") or "INR" %}
{%- set sym         = frappe.db.get_value("Currency", currency, "symbol") or "&#8377;" %}
{%- set footer_note = company_doc.get("custom_voucher_footer_note") or
    "This is a computer-generated write-off voucher. Valid without physical stamp unless specified by policy." %}

{%- set _owner_name = frappe.db.get_value("User", doc.owner, "full_name") or doc.owner %}
{%- set student = frappe.get_cached_doc("Ex Student", doc.ex_student) %}

<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Fee Write-Off — {{ doc.name }}</title>
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: 'Segoe UI', Arial, sans-serif; font-size: 12px; color: #1a1a2e; background: #fff; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  .page { width: 100%; max-width: 210mm; margin: 0 auto; padding: 5mm 8mm 6mm; display: flex; flex-direction: column; gap: 0; }

  /* HEADER — red accent for Write-Off */
  .header { display: grid; grid-template-columns: 90px 1fr 175px; gap: 10px; align-items: flex-start; padding-bottom: 10px; border-bottom: 2.5px solid #B0321B; }
  .logo-wrap img { width: 82px; height: auto; max-height: 60px; object-fit: contain; display: block; }
  .co-name { font-size: 14px; font-weight: 700; color: #B0321B; margin-bottom: 4px; }
  .co-meta { font-size: 9.5px; color: #555; line-height: 1.65; }
  .doc-title-block { text-align: right; }
  .vch-label { font-size: 13px; font-weight: 700; color: #B0321B; letter-spacing: 1px; text-transform: uppercase; }
  .doc-no-pill { display: inline-block; margin-top: 5px; background: #FBEAE5; color: #4A1208; font-size: 11px; font-weight: 700; padding: 3px 10px; border-radius: 4px; }
  .date-label { font-size: 8.5px; color: #888; text-transform: uppercase; letter-spacing: 0.5px; margin-top: 7px; }
  .date-value { font-size: 12px; font-weight: 600; color: #1a1a2e; margin-top: 2px; }

  /* META STRIP */
  .meta-strip { display: grid; grid-template-columns: 1fr 1fr; border: 0.5px solid #e5b8ae; border-top: none; }
  .mc { padding: 7px 11px; border-right: 0.5px solid #e5b8ae; }
  .mc:last-child { border-right: none; }
  .mc-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.6px; color: #888; margin-bottom: 3px; }
  .mc-value { font-size: 11px; font-weight: 600; color: #1a1a2e; }

  /* SECTION TITLE */
  .sec-title { background: #FDF4F1; border-top: 0.5px solid #e5b8ae; border-bottom: 0.5px solid #e5b8ae; padding: 5px 11px; font-size: 8.5px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.7px; color: #B0321B; margin-top: 6px; }

  /* KEY-VALUE TABLE */
  table.kv { width: 100%; border-collapse: collapse; border: 0.5px solid #e5b8ae; border-top: none; }
  table.kv td { padding: 7px 11px; border-bottom: 0.5px solid #f7e5e0; vertical-align: middle; font-size: 11px; color: #1a1a2e; }
  table.kv tr:last-child td { border-bottom: none; }
  table.kv td.k { width: 170px; font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #888; font-weight: 700; border-right: 0.5px solid #f7e5e0; background: #fdf9f7; }
  table.kv td.v { font-size: 12px; font-weight: 600; color: #1a1a2e; }
  table.kv td.v-big { font-size: 14px; font-weight: 700; color: #B0321B; }

  /* REASON BLOCK */
  .reason-block { border: 1px solid #e5b8ae; border-top: none; padding: 10px 14px; background: #FDF4F1; }
  .reason-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #888; margin-bottom: 4px; font-weight: 700; }
  .reason-value { font-size: 12px; color: #333; line-height: 1.5; font-style: italic; }

  /* TOTALS BAR */
  .totals-bar { display: flex; justify-content: space-between; align-items: center; padding: 9px 11px; border: 0.5px solid #e5b8ae; border-top: 1.5px solid #B0321B; background: #FDF4F1; margin-top: 6px; }
  .w-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #888; margin-bottom: 3px; }
  .w-value { font-size: 10.5px; font-style: italic; color: #B0321B; font-weight: 600; max-width: 340px; }
  .a-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #888; margin-bottom: 2px; text-align: right; }
  .a-value { font-size: 22px; font-weight: 700; color: #B0321B; text-align: right; }

  /* OUTSTANDING TABLE */
  table.os { width: 100%; border-collapse: collapse; border: 0.5px solid #e5b8ae; border-top: none; }
  table.os td { padding: 7px 11px; border-bottom: 0.5px solid #f7e5e0; font-size: 11px; }
  table.os tr:last-child td { border-bottom: none; }
  table.os td.k { color: #555; }
  table.os td.r { text-align: right; font-variant-numeric: tabular-nums; font-family: 'Courier New', monospace; font-size: 11.5px; white-space: nowrap; }
  table.os tr.total td { background: #FDF4F1; font-weight: 700; color: #B0321B; border-top: 1.5px solid #B0321B; }

  /* REMARKS */
  .remarks-block { border: 0.5px solid #e5b8ae; border-top: none; padding: 7px 11px; }
  .r-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #888; margin-bottom: 3px; }
  .r-value { font-size: 11px; color: #333; line-height: 1.5; }

  /* SIGNATURES */
  .sig-strip { display: grid; grid-template-columns: 1fr 1fr 1fr; border: 0.5px solid #e5b8ae; margin-top: 14px; }
  .sig-cell { padding: 7px 14px 9px; border-right: 0.5px solid #e5b8ae; text-align: center; }
  .sig-cell:last-child { border-right: none; }
  .sig-space { height: 34px; }
  .sig-line { border-top: 1px solid #B0321B; margin-bottom: 4px; }
  .sig-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.6px; color: #555; }
  .sig-name  { font-size: 9px; color: #B0321B; font-weight: 600; margin-top: 2px; }

  /* PAGE FOOTER */
  .page-footer { margin-top: 10px; padding-top: 8px; border-top: 0.5px solid #e5b8ae; display: flex; justify-content: space-between; align-items: center; }
  .page-footer .note { font-size: 8.5px; color: #aaa; font-style: italic; max-width: 480px; }
  .page-footer .brand { font-size: 8.5px; color: #aaa; white-space: nowrap; }
  .page-footer .brand strong { color: #B0321B; }

  @media print {
    body { background: white; }
    .page { padding: 3mm 5mm; margin: 0; width: 100%; max-width: 100%; }
    @page { size: A4; margin: 10mm; }
  }
</style>
</head>
<body>
<div class="page">

  <div class="header">
    <div class="logo-wrap">
      <img src="{{ logo_url }}" alt="{{ company_doc.company_name or doc.company }}">
    </div>
    <div>
      <div class="co-name">{{ company_doc.company_name or doc.company }}</div>
      <div class="co-meta">
        {%- if company_doc.get("gstin") %}GSTIN: {{ company_doc.gstin }}{%- if company_doc.get("tax_id") %} &nbsp;|&nbsp; PAN: {{ company_doc.tax_id }}{%- endif %}<br>{%- elif company_doc.get("tax_id") %}PAN: {{ company_doc.tax_id }}<br>{%- endif %}
        {%- set addr_id = frappe.db.get_value("Dynamic Link", {"link_doctype": "Company", "link_name": company_doc.name, "parenttype": "Address"}, "parent") %}
        {%- if addr_id %}
          {%- set a = frappe.get_doc("Address", addr_id) %}
          {%- set addr_parts = [a.address_line1, a.address_line2, a.city, a.state, a.pincode] | select | join(", ") %}
          {{ addr_parts }}<br>
        {%- endif %}
        {%- if company_doc.get("phone_no") %}Ph: {{ company_doc.phone_no }}{%- endif %}{%- if company_doc.get("phone_no") and company_doc.get("email") %} &nbsp;|&nbsp; {%- endif %}{%- if company_doc.get("email") %}{{ company_doc.email }}{%- endif %}
      </div>
    </div>
    <div class="doc-title-block">
      <div class="vch-label">Fee Write-Off</div>
      <div><span class="doc-no-pill">{{ doc.name }}</span></div>
      <div class="date-label">Date</div>
      <div class="date-value">{{ frappe.format(doc.posting_date, {"fieldtype": "Date"}) }}</div>
    </div>
  </div>

  <div class="meta-strip">
    <div class="mc">
      <div class="mc-label">Write-Off Account</div>
      <div class="mc-value">{{ doc.get("writeoff_account") or "&#8212;" }}</div>
    </div>
    <div class="mc">
      <div class="mc-label">Against</div>
      <div class="mc-value">Ex-Students Receivable</div>
    </div>
  </div>

  <div class="sec-title">Student</div>
  <table class="kv">
    <tr>
      <td class="k">Student Name</td>
      <td class="v v-big">{{ doc.student_name or doc.ex_student }}</td>
    </tr>
    <tr>
      <td class="k">Student ID</td>
      <td class="v">{{ student.student_id or "&#8212;" }}</td>
    </tr>
    <tr>
      <td class="k">Course / Batch</td>
      <td class="v">
        {{ student.course or "&#8212;" }}
        {%- if student.batch_year %} &nbsp;&middot;&nbsp; Batch {{ student.batch_year }}{%- endif %}
      </td>
    </tr>
    <tr>
      <td class="k">Admission Session</td>
      <td class="v">{{ student.admission_session or "&#8212;" }}</td>
    </tr>
    {%- if student.father_name %}
    <tr>
      <td class="k">Father's Name</td>
      <td class="v">{{ student.father_name }}</td>
    </tr>
    {%- endif %}
  </table>

  <div class="sec-title">Reason</div>
  <div class="reason-block">
    <div class="reason-value">{{ doc.reason or "&#8212;" }}</div>
  </div>

  <div class="totals-bar">
    <div>
      <div class="w-label">Amount in words</div>
      <div class="w-value">
        {%- set _words = frappe.utils.money_in_words(doc.amount, main_currency=currency) or "&#8212;" %}
        {{ _words.replace("INR ", "").replace("USD ", "").replace("EUR ", "") if _words != "&#8212;" else "&#8212;" }}
      </div>
    </div>
    <div>
      <div class="a-label">Amount Written Off</div>
      <div class="a-value">{{ frappe.utils.fmt_money(doc.amount, currency=currency) }}</div>
    </div>
  </div>

  <div class="sec-title">Outstanding Ledger</div>
  <table class="os">
    <tr>
      <td class="k">Outstanding before this write-off</td>
      <td class="r">{{ frappe.utils.fmt_money(doc.outstanding_before, currency=currency) }}</td>
    </tr>
    <tr>
      <td class="k">Less: Amount written off</td>
      <td class="r">&#8722;&nbsp;{{ frappe.utils.fmt_money(doc.amount, currency=currency) }}</td>
    </tr>
    <tr class="total">
      <td class="k">Outstanding after this write-off</td>
      <td class="r">{{ frappe.utils.fmt_money(doc.outstanding_after, currency=currency) }}</td>
    </tr>
  </table>

  {%- if doc.get("remarks") %}
  <div class="remarks-block">
    <div class="r-label">Remarks</div>
    <div class="r-value">{{ doc.remarks }}</div>
  </div>
  {%- endif %}

  <div class="sig-strip">
    <div class="sig-cell">
      <div class="sig-space"></div>
      <div class="sig-line"></div>
      <div class="sig-label">Prepared By</div>
      <div class="sig-name">{{ _owner_name }}</div>
    </div>
    <div class="sig-cell">
      <div class="sig-space"></div>
      <div class="sig-line"></div>
      <div class="sig-label">Approved By</div>
    </div>
    <div class="sig-cell">
      <div class="sig-space"></div>
      <div class="sig-line"></div>
      <div class="sig-label">Authorised Signatory</div>
    </div>
  </div>

  <div class="page-footer">
    <div class="note">{{ footer_note }}</div>
    <div class="brand">Powered by <strong>DUX DigiTech</strong></div>
  </div>

</div>
</body>
</html>
